def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    # The 5 marks the starting horizontal position in the output.
    marker = next(
        (c - 8 for row in grid for c, value in enumerate(row) if value == 5),
        0
    )
    x = max(0, min(6, marker))
    out[0][x] = 5

    # Read the 3x3 tiles top-to-bottom in the left column, then
    # top-to-bottom in the right column.
    tiles = []
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            color = next(
                (grid[r][c] for r in range(top, top + 3)
                 for c in range(left, left + 3)
                 if grid[r][c] not in (0, 4, 5)),
                None
            )
            if color is not None:
                tiles.append(color)

    y = 1
    for color in tiles:
        if color == 6:
            for _ in range(2):
                if y < h:
                    out[y][x] = 6
                    y += 1
        else:
            if color == 1:
                start, end = x, x + 2
                x += 2
            elif color == 2:
                start, end = x - 1, x
                x -= 1
            elif color == 3:
                start, end = x - 3, x
                x -= 3
            else:
                continue

            if y < h:
                for c in range(max(0, start), min(7, end + 1)):
                    out[y][c] = color
                y += 1

    return out
